[[ ## document ## ]]
{
  "title": "Stonebridge Property Group 2025 Form 1065 PBC Request",
  "path": "engagements/stonebridge-property-group/1065/2025/pbc-request.docx",
  "document": {
    "blocks": [
      {
        "kind": "heading",
        "level": 1,
        "text": "Stonebridge Property Group — 2025 Form 1065"
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "Prepared-by-Client (PBC) Request"
      },
      {
        "kind": "paragraph",
        "text": "Tax year ending December 31, 2025. Please provide the items below to Lucia Mendes (lmendes@stonebridge.com) by February 14, 2026. If any item is not applicable to Stonebridge Property Group, confirm that in writing so we can close the request."
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "Financial Information"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "Final trial balance as of December 31, 2025, in Excel, with account-level detail and a reconciliation to the prior-year return.",
          "General ledger detail for all cash, receivables, payables, and intercompany accounts for the full year.",
          "Bank statements for all operating, reserve, and lockbox accounts for January–December 2025, including any statements for accounts opened or closed during the year.",
          "Year-end bank reconciliations for each account, with outstanding items listed and aged.",
          "Fixed asset rollforward: additions, disposals, depreciation expense, and accumulated depreciation by asset class.",
          "Loan statements and amortization schedules for all mortgages and notes payable, including principal/interest split and any prepayment penalties.",
          "Schedule of capital contributions and distributions by partner for the full year."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "Partner and Ownership Information"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "Updated partner K-1 mailing addresses and tax identification numbers, with any changes from 2024.",
          "Copies of all executed partnership agreements, amendments, and side letters in effect during 2025.",
          "Schedule of any transfers, redemptions, or admissions of partners during the year, with effective dates and amounts.",
          "Documentation of any guaranteed payments, including the calculation and the partner to whom paid."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "Rental and Property Operations"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "Rent roll as of December 31, 2025, showing unit, tenant, monthly rent, security deposits, and vacancy status.",
          "Lease schedule for all leases active during 2025, with commencement and expiration dates, rent abatements, and tenant improvement allowances.",
          "Schedule of tenant improvements capitalized during the year, with costs and in-service dates.",
          "Real estate tax bills and assessed values for all properties, plus any appeals or refunds received.",
          "Insurance policies in force during 2025, with premiums paid and any claims filed or settled.",
          "CAM (common area maintenance) reconciliation for each property, with actual vs. billed amounts."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "Tax-Specific Items"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "Section 179 and bonus depreciation schedules, including any election statements filed or to be filed.",
          "List of all tangible property placed in service during 2025, with dates and costs, for cost segregation review.",
          "Documentation of any like-kind exchanges under IRC 1031, including the qualified intermediary and timeline.",
          "Schedule of any debt cancellation, foreclosure, or abandonment of property during the year.",
          "All Forms 1099 received by the partnership (interest, dividends, proceeds, etc.).",
          "Any state or local tax notices, assessments, or correspondence received in 2025."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "Prior-Year and Compliance Documents"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "Copy of the 2024 Form 1065 and all K-1s for reference.",
          "Any extension payments made for 2025, with confirmation numbers.",
          "Documentation of estimated tax payments made by the partnership during 2025.",
          "Any IRS or state correspondence received during 2025 (other than routine notices)."
        ]
      },
      {
        "kind": "paragraph",
        "text": "Please upload documents to the shared folder: eng/stonebridge-property-group/2025/pbc/. If a document is large or you prefer to email, that is fine — just flag it so we track receipt. We will confirm each item as it arrives. Thank you for getting this to us by February 14."
      },
      {
        "kind": "paragraph",
        "text": "Regards,\nLucia Mendes\nSenior Accountant, Tax\nStonebridge & Associates"
      }
    ]
  }
}
[[ ## completed ## ]]
